#include <iostream>
using namespace std;

int main() {
    int arr[100], n, pos, value;

    cout << "Enter number of elements: ";
    cin >> n;

    cout << "Enter array elements:\n";
    for(int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    cout << "Enter position to insert (1-" << n + 1 << "): ";
    cin >> pos;

    if(pos < 1 || pos > n + 1) {
        cout << "Invalid Position";
        return 0;
    }

    cout << "Enter value to insert: ";
    cin >> value;

    for(int i = n; i >= pos; i--) {
        arr[i] = arr[i - 1];
    }

    arr[pos - 1] = value;
    n++;

    cout << "Array after insertion: ";
    for(int i = 0; i < n; i++) {
        cout << arr[i] << " ";
    }

    return 0;
}

#include<iostream>
using namespace std;

int main() {
    int arr[100], n, pos;
    cout << "Enter number of elements: ";
    cin >> n;
    cout << "Enter array elements:\n";
    for(int i=0;i<n;i++) cin >> arr[i];
    cout << "Enter position to delete (1-" << n << "): ";
    cin >> pos;
    if(pos<1 || pos>n){
        cout << "Invalid Position";
        return 0;
    }
    for(int i=pos-1;i<n-1;i++) arr[i]=arr[i+1];
    n--;
    cout << "Array after deletion: ";
    for(int i=0;i<n;i++) cout << arr[i] << " ";
    return 0;
}

